import { describe, it, expect, vi, beforeEach } from 'vitest';
import { CancelSubscriptionUseCase } from './CancelSubscriptionUseCase';
import { SubscriptionId } from '../domain/SubscriptionId';
import { Subscription } from '../domain/Subscription';
import { SubscriptionStatus } from '../domain/SubscriptionStatus';
import { DomainEventPublisher } from '../domain/DomainEventPublisher';
import { SubscriptionCancelledEvent } from '../domain/events/SubscriptionCancelledEvent';
import { Result } from '../domain/Result';

// Mock repository implementation
class MockSubscriptionRepository {
  private subscriptions: Map<string, Subscription> = new Map();

  async findById(id: SubscriptionId): Promise<Subscription | null> {
    return this.subscriptions.get(id.value) || null;
  }

  async save(subscription: Subscription): Promise<void> {
    this.subscriptions.set(subscription.id.value, subscription);
  }

  async delete(id: SubscriptionId): Promise<void> {
    this.subscriptions.delete(id.value);
  }
}

describe('CancelSubscriptionUseCase', () => {
  let mockRepository: MockSubscriptionRepository;
  let mockEventPublisher: DomainEventPublisher;
  let useCase: CancelSubscriptionUseCase;

  beforeEach(() => {
    mockRepository = new MockSubscriptionRepository();
    mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);
  });

  describe('Arrange-Act-Assert Pattern', () => {
    it('should successfully cancel an active subscription and publish event', async () => {
      // Arrange
      const subscriptionId = new SubscriptionId('sub-123');
      const subscription = new Subscription(
        subscriptionId,
        'user-456',
        SubscriptionStatus.ACTIVE,
        new Date('2023-01-01'),
        new Date('2023-12-31')
      );

      await mockRepository.save(subscription);

      // Act
      const result = await useCase.execute(subscriptionId);

      // Assert
      expect(result.isSuccess).toBe(true);
      expect(result.value).toBeUndefined();

      // Verify subscription is cancelled
      const updatedSubscription = await mockRepository.findById(subscriptionId);
      expect(updatedSubscription).not.toBeNull();
      expect(updatedSubscription!.status).toBe(SubscriptionStatus.CANCELLED);

      // Verify event was published
      expect(mockEventPublisher.publish).toHaveBeenCalledWith(
        new SubscriptionCancelledEvent(subscriptionId)
      );
    });

    it('should return error when subscription does not exist', async () => {
      // Arrange
      const nonExistentId = new SubscriptionId('non-existent');

      // Act
      const result = await useCase.execute(nonExistentId);

      // Assert
      expect(result.isSuccess).toBe(false);
      expect(result.error).toBeDefined();
      expect(mockEventPublisher.publish).not.toHaveBeenCalled();
    });

    it('should return error when subscription is already cancelled', async () => {
      // Arrange
      const subscriptionId = new SubscriptionId('sub-123');
      const subscription = new Subscription(
        subscriptionId,
        'user-456',
        SubscriptionStatus.CANCELLED,
        new Date('2023-01-01'),
        new Date('2023-12-31')
      );

      await mockRepository.save(subscription);

      // Act
      const result = await useCase.execute(subscriptionId);

      // Assert
      expect(result.isSuccess).toBe(false);
      expect(result.error).toBeDefined();
      expect(mockEventPublisher.publish).not.toHaveBeenCalled();
    });
  });
