      if (!subscription) {
        // Note: In a real implementation, you'd want to return a proper error type for missing subscription
        throw new Error('Subscription not found');
      }

      // Invariant rule: Cannot cancel already expired subscription
      if (subscription.status === 'expired') {
        return error(new SubscriptionAlreadyExpiredError());
