// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    try {
      // Validate input
      if (!request.userId) {
        return error(new InvalidPasswordError('User ID is required'));
      }

      if (!request.currentPassword) {
        return error(new InvalidPasswordError('Current password is required'));
      }

      if (!request.newPassword) {
        return error(new InvalidPasswordError('New password is required'));
      }

      // Fetch user
      const user = await this.userRepository.findById(request.userId);
      if (!user) {
        return error(new PasswordMismatchError('User not found'));
      }

      // Verify current password
      const isPasswordValid = await this.passwordHasher.compare(
        request.currentPassword,
        user.passwordHash
      );

      if (!isPasswordValid) {
        return error(new PasswordMismatchError('Current password is incorrect'));
      }

      // Business rule: new password cannot equal old password
      const isSamePassword = await this.passwordHasher.compare(
        request.newPassword,
        user.passwordHash
      );

      if (isSamePassword) {
        return error(new InvalidPasswordError('New password cannot be the same as the current password'));
      }

      // Hash new password
      const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

      // Update user password
      user.passwordHash = newPasswordHash;
      await this.userRepository.update(user);

      return ok(undefined);
    } catch (err) {
      if (err instanceof DomainError) {
        return error(err);
      }
      return error(new InvalidPasswordError('Failed to change password'));
    }
  }
}

// Application/Result.ts
export type Result<T, E extends DomainError> = {
  isSuccess: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value,
  };
}

export function error<E extends DomainError>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error,
  };
}
